import land.nithi.life.*;
import java.util.Arrays;
public class EngineJavaTest {
    static void check(boolean b){if(!b)throw new AssertionError("Engine regression");}
    public static void main(String[] args){LifeEngine e=new LifeEngine();e.borders=true;e.pattern(8);byte[] block=e.cells.clone();for(int i=0;i<10;i++)e.step(false);check(Arrays.equals(block,e.cells));e.pattern(7);byte[] blinker=e.cells.clone();e.step(true);check(!Arrays.equals(blinker,e.cells));e.step(true);check(Arrays.equals(blinker,e.cells));e.undo();check(e.generation==1);e.undo();check(e.generation==0);e.pattern(0);for(int i=0;i<4;i++)e.step(false);check(e.population()==5&&e.cells[49*160+80]==1);e.clear();e.wrap=true;e.set(159,0,true);e.set(0,0,true);e.set(1,0,true);e.step(true);check(e.cells[99*160]==1&&e.cells[0]==1&&e.cells[160]==1);e.undo();e.wrap=false;e.step(false);check(e.population()==0);for(int[] pair:new int[][]{{1,3},{6,15}}){e.pattern(pair[0]);byte[] seed=e.cells.clone();for(int i=0;i<pair[1];i++)e.step(false);check(Arrays.equals(seed,e.cells));}for(int i=0;i<120;i++)e.checkpoint();check(e.history.size()==96);e.pattern(0);e.set(1,1,true);byte[] initial=e.cells.clone();e.step(true);e.step(true);e.restart();check(e.generation==0&&Arrays.equals(initial,e.cells));e.pattern(0);e.step(true);byte[] evolved=e.cells.clone();e.checkpoint();e.set(1,1,true);e.undo();check(e.generation==1&&Arrays.equals(evolved,e.cells));e.checkpoint();e.set(2,2,true);e.back();check(e.generation==0&&e.population()==5);e.redo();check(e.generation==1&&e.cells[2*160+2]==1);e.undo();e.checkpoint();e.set(3,3,true);check(e.redos.isEmpty());e.cursorX=e.cursorY=0;e.moveCursor(-1,0,false);check(e.cursorX==0);e.moveCursor(1,0,true);e.moveCursor(0,1,true);check(e.selected.equals(new java.util.HashSet<>(java.util.Arrays.asList(0,1,161))));e.clear();e.selected.clear();e.selected.addAll(java.util.Arrays.asList(0,1,161));e.editSelection(1);check(e.population()==3);e.editSelection(2);check(e.population()==0);e.undo();check(e.population()==3);e.redo();check(e.population()==0);e.editSelection(1);e.editSelection(0);check(e.population()==0);e.selected.clear();e.editSelection(2);check(e.population()==1);e.editSelection(2);check(e.population()==0);LifeEngine overlay=new LifeEngine();overlay.set(0,0,true);overlay.place(new String[]{"O.O"},0,0);check(overlay.population()==3&&overlay.alive(0,0));overlay.place(new String[]{"O.O"},0,0,true);check(overlay.population()==2&&!overlay.alive(0,0));overlay.name="Named Chart";overlay.undo();check(overlay.population()==3&&overlay.name.equals("Named Chart"));overlay.restart();check(overlay.name.equals("Named Chart"));LifeEngine n=new LifeEngine();check(!n.borders);for(int x=-1;x<=1;x++)n.set(x,-1,true);n.step(true);check(n.population()==3&&n.alive(0,-2)&&n.alive(0,0));n.undo();check(n.alive(-1,-1)&&n.generation==0);n.redo();check(n.alive(0,-2));n.clear();n.place(new String[]{".O.","..O","OOO"},159,99);java.util.HashSet<LifeEngine.Cell> points=n.live(),expected=new java.util.HashSet<>();for(LifeEngine.Cell p:points)expected.add(new LifeEngine.Cell(p.x+1,p.y+1));for(int i=0;i<4;i++)n.step(true);check(n.live().equals(expected));n.restart();check(n.live().equals(points));n.clear();n.set(-10,-10,true);n.set(-9,-10,true);n.select(-10,-10);n.select(-9,-10);String[] rows=n.copiedRows();n.set(900,900,true);n.place(rows,-40,-50);check(n.alive(-41,-50)&&n.alive(-40,-50)&&n.alive(900,900));n.undo();check(!n.alive(-41,-50)&&n.alive(900,900));n.redo();n.configureBorders(true,20,20);check(n.population()==0);n.undo();check(!n.borders&&n.alive(900,900));n.clear();n.configureBorders(true,5,5);n.configureRules(0,0,8);n.set(2,2,true);n.step(true);check(n.alive(2,2)&&n.equilibrium);n.configureRules(2,3,3);n.step(true);check(n.population()==0);n.randomize(1);check(n.population()==25);n.randomize(0);check(n.population()==0);System.out.println("Java infinite coordinates, border undo, clipboard placement, rules, equilibrium and density endpoints passed.");System.out.println("Java engine: still life, oscillator, glider, wrap, undo, periods and bounded history passed.");}
}
